mapper.select:
SELECT p.* FROM cat_product p JOIN mer_merchant m ON m.id=p.merchant_id LEFT JOIN cat_category c ON c.code=p.category_code WHERE p.status='PUBLISHED' AND m.status='ACTIVE' AND EXISTS (SELECT 1 FROM cat_sku active_s WHERE active_s.product_id=p.id AND active_s.status='ACTIVE') AND (
(LOCATE(LOWER(#{term}),LOWER(CONCAT_WS(' ',p.title,p.description,c.name,m.name))) > 0 OR EXISTS (SELECT 1 FROM cat_sku s WHERE s.product_id=p.id AND s.status='ACTIVE' AND LOCATE(LOWER(#{term}),LOWER(s.spec_key)) > 0))
) ORDER BY (
(CASE WHEN LOCATE(LOWER(#{term}),LOWER(p.title)) > 0 THEN 6 ELSE 0 END + CASE WHEN LOCATE(LOWER(#{term}),LOWER(p.description)) > 0 THEN 3 ELSE 0 END + CASE WHEN LOCATE(LOWER(#{term}),LOWER(COALESCE(c.name,''))) > 0 THEN 1 ELSE 0 END + CASE WHEN EXISTS (SELECT 1 FROM cat_sku s WHERE s.product_id=p.id AND s.status='ACTIVE' AND LOCATE(LOWER(#{term}),LOWER(s.spec_key)) > 0) THEN 4 ELSE 0 END)
) DESC,p.created_at DESC,p.id LIMIT #{limit}

SELECT COUNT(*) FROM cat_product p WHERE p.merchant_id=#{merchantId}
AND (
  LOCATE(LOWER(#{query}),LOWER(p.title)) > 0 OR LOCATE(LOWER(#{query}),LOWER(p.description)) > 0
  OR EXISTS (SELECT 1 FROM cat_sku s WHERE s.product_id=p.id AND
    (LOCATE(LOWER(#{query}),LOWER(s.id)) > 0 OR LOCATE(LOWER(#{query}),LOWER(s.spec_key)) > 0))
)
AND p.category_code=#{category}
AND p.status=#{status}
